import React, { useState, useEffect, useRef } from 'react';
import './Header.css';

// Options d'autocomplétion (mock data basées sur les patients et demandes)
const autocompleteSuggestions = [
  "Castres", "Toulouse", "Albi", "Mazamet", "Paris",
  "Marie Dubois", "François Dupont", "Jean Martin", "Sophie Laurent",
  "Consultation", "Urgence", "Dialyse", "Radiothérapie"
];

const Header = ({ user, onSearch }) => {
  const [query, setQuery] = useState('');
  const [showDropdown, setShowDropdown] = useState(false);
  const searchRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (searchRef.current && !searchRef.current.contains(event.target)) {
        setShowDropdown(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleChange = (e) => {
    const value = e.target.value;
    setQuery(value);
    setShowDropdown(true);
    if (onSearch) onSearch(value);
  };

  const handleSelect = (suggestion) => {
    setQuery(suggestion);
    setShowDropdown(false);
    if (onSearch) onSearch(suggestion);
  };

  // Recherche par préfixe : on vérifie si la suggestion commence par la requête (ignorer la casse)
  const filteredSuggestions = query.trim() === ''
    ? []
    : autocompleteSuggestions.filter(item =>
      item.toLowerCase().startsWith(query.toLowerCase())
    );

  return (
    <header className="header">
      <div className="search-container" ref={searchRef}>
        <div className="search-box">
          <span className="search-icon">🔍</span>
          <input
            type="text"
            placeholder="Rechercher par préfixe (ex: Cas, Ma)..."
            className="search-input"
            value={query}
            onChange={handleChange}
            onFocus={() => setShowDropdown(true)}
          />
        </div>

        {showDropdown && query.trim() !== '' && filteredSuggestions.length > 0 && (
          <div className="search-dropdown autocomplete-dropdown">
            {filteredSuggestions.map((suggestion, index) => {
              // On met en gras la partie tapée par l'utilisateur (le préfixe)
              const matchLen = query.length;
              return (
                <div
                  key={index}
                  className="search-dropdown-item autocomplete-item"
                  onClick={() => handleSelect(suggestion)}
                >
                  <strong>{suggestion.substring(0, matchLen)}</strong>
                  {suggestion.substring(matchLen)}
                </div>
              );
            })}
          </div>
        )}
      </div>

      <div className="header-actions">
        {user && (
          <div style={{ marginRight: '16px', fontWeight: '500', color: '#1e293b' }}>
            Bonjour, {user.firstName} 👋
          </div>
        )}
        <div className="notification-icon">
          🔔
          <span className="notification-badge">1</span>
        </div>
      </div>
    </header>
  );
};

export default Header;
